#' Table One (Python Core)
#'
#' 
#' @param data .
#' @param vars .
#' @param cont .
#' @param excl .
#' @param showAllLevels .
#' @param showSummary .
#' @param showAbout .
#' @param showReportSentence .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$continuous} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$categories} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$eligibility} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$about} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$report} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pytableone <- function(
    data,
    vars = NULL,
    cont = "mean",
    excl = FALSE,
    showAllLevels = FALSE,
    showSummary = FALSE,
    showAbout = FALSE,
    showReportSentence = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pytableone requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))


    options <- pytableoneOptions$new(
        vars = vars,
        cont = cont,
        excl = excl,
        showAllLevels = showAllLevels,
        showSummary = showSummary,
        showAbout = showAbout,
        showReportSentence = showReportSentence,
        showConsole = showConsole)

    analysis <- pytableoneClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

